const response = $input.first().json;
const html = response.body || response.data || '';
const htmlStr = typeof html === 'string' ? html : JSON.stringify(html);
const url = $node['Fetch Page'].json.url || $node['Webhook - Analyze Meta'].json.body?.url || '';

// Extract meta tags
const titleMatch = htmlStr.match(/<title[^>]*>([^<]*)<\/title>/i);
const descMatch = htmlStr.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["']/i) ||
                  htmlStr.match(/<meta[^>]*content=["']([^"']*)["'][^>]*name=["']description["']/i);
const h1Match = htmlStr.match(/<h1[^>]*>([^<]*)<\/h1>/i);
const canonicalMatch = htmlStr.match(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']*)["']/i);
const ogTitleMatch = htmlStr.match(/<meta[^>]*property=["']og:title["'][^>]*content=["']([^"']*)["']/i);
const ogDescMatch = htmlStr.match(/<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']*)["']/i);

const title = titleMatch ? titleMatch[1].trim() : '';
const description = descMatch ? descMatch[1].trim() : '';
const h1 = h1Match ? h1Match[1].trim() : '';
const canonical = canonicalMatch ? canonicalMatch[1].trim() : '';
const ogTitle = ogTitleMatch ? ogTitleMatch[1].trim() : '';
const ogDesc = ogDescMatch ? ogDescMatch[1].trim() : '';

// Analyze issues
const issues = [];
const suggestions = [];

// Title analysis
if (!title) {
  issues.push({ field: 'title', severity: 'critical', message: 'Missing title tag' });
} else {
  if (title.length < 30) issues.push({ field: 'title', severity: 'warning', message: `Title too short (${title.length} chars, recommend 50-60)` });
  if (title.length > 60) issues.push({ field: 'title', severity: 'warning', message: `Title too long (${title.length} chars, may be truncated)` });
}

// Description analysis
if (!description) {
  issues.push({ field: 'description', severity: 'high', message: 'Missing meta description' });
  suggestions.push({ field: 'description', suggestion: `Write a compelling 150-160 char description for: ${url}` });
} else {
  if (description.length < 120) issues.push({ field: 'description', severity: 'warning', message: `Description too short (${description.length} chars, recommend 150-160)` });
  if (description.length > 160) issues.push({ field: 'description', severity: 'info', message: `Description may be truncated (${description.length} chars)` });
}

// H1 analysis
if (!h1) {
  issues.push({ field: 'h1', severity: 'high', message: 'Missing H1 tag' });
} else if (h1 === title) {
  issues.push({ field: 'h1', severity: 'info', message: 'H1 identical to title (consider differentiating)' });
}

// Canonical
if (!canonical) {
  issues.push({ field: 'canonical', severity: 'medium', message: 'Missing canonical tag' });
}

// Open Graph
if (!ogTitle) issues.push({ field: 'og:title', severity: 'low', message: 'Missing og:title' });
if (!ogDesc) issues.push({ field: 'og:description', severity: 'low', message: 'Missing og:description' });

// Schema markup check
const hasSchema = htmlStr.includes('application/ld+json') || htmlStr.includes('itemtype');
if (!hasSchema) {
  issues.push({ field: 'schema', severity: 'medium', message: 'No structured data (schema.org) detected' });
  suggestions.push({ field: 'schema', suggestion: 'Add JSON-LD structured data for better SERP appearance' });
}

// Score
let score = 100;
for (const issue of issues) {
  if (issue.severity === 'critical') score -= 25;
  else if (issue.severity === 'high') score -= 15;
  else if (issue.severity === 'medium') score -= 10;
  else if (issue.severity === 'warning') score -= 5;
  else score -= 2;
}

return [{
  json: {
    url: url,
    score: Math.max(0, score),
    current: { title, description, h1, canonical, og_title: ogTitle, og_description: ogDesc, has_schema: hasSchema },
    title_length: title.length,
    description_length: description.length,
    issues: issues,
    suggestions: suggestions,
    issue_count: issues.length,
    needs_attention: score < 70
  }
}];

